import{processInboundWebhook}from"@/features/integrations/services/inboundWebhookService";import{toApiError}from"@/lib/api/errors";export async function POST(request:Request,context:RouteContext<"/api/external/v1/inbound/[endpointKey]">){const requestId=request.headers.get("x-request-id")?.slice(0,64)??crypto.randomUUID();try{return Response.json({ok:true,data:await processInboundWebhook((await context.params).endpointKey,request),meta:{request_id:requestId}},{headers:{"cache-control":"no-store","x-request-id":requestId}});}catch(error){const app=toApiError(error);return Response.json({ok:false,error:{code:app.code,message:app.message,request_id:requestId}},{status:app.status,headers:{"cache-control":"no-store","x-request-id":requestId}});}}
